import itertools
from solution import minPath

import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# ---------- reference model (obviously correct brute force) ----------

def _pos_of(grid, value):
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v == value:
                return (i, j)
    raise AssertionError("value not in grid")


def _are_adjacent(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1]) == 1


def brute_min_path(grid, k):
    n = len(grid)
    # map value -> pos (values are 1..n*n unique)
    val_to_pos = {}
    for i in range(n):
        for j in range(n):
            val_to_pos[grid[i][j]] = (i, j)

    best = None
    # enumerate all walks of k cells
    def dfs(path_vals, r, c):
        nonlocal best
        # prune: if prefix already larger than best prefix, stop
        if best is not None:
            # compare prefix
            # if path_vals > best[:len(path_vals)] lexicographically, prune
            bpre = best[:len(path_vals)]
            if path_vals > bpre:
                return
        if len(path_vals) == k:
            if best is None or path_vals < best:
                best = list(path_vals)
            return
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                path_vals.append(grid[nr][nc])
                dfs(path_vals, nr, nc)
                path_vals.pop()

    for i in range(n):
        for j in range(n):
            dfs([grid[i][j]], i, j)
    return best


def _is_valid_walk_values(grid, vals):
    if len(vals) == 0:
        return False
    n = len(grid)
    val_to_pos = {}
    for i in range(n):
        for j in range(n):
            val_to_pos[grid[i][j]] = (i, j)
    # all values in range
    for v in vals:
        if v not in val_to_pos:
            return False
    for a, b in zip(vals, vals[1:]):
        if not _are_adjacent(val_to_pos[a], val_to_pos[b]):
            return False
    return True


def _random_grid_strategy(n_min=2, n_max=3):
    # draw n then permutation
    return st.integers(min_value=n_min, max_value=n_max).flatmap(
        lambda n: st.permutations(list(range(1, n * n + 1))).map(
            lambda perm: [list(perm[i * n:(i + 1) * n]) for i in range(n)]
        )
    )


# ---------- spec examples ----------

def test_spec_example_1():
    assert minPath([[1, 2, 3], [4, 5, 6], [7, 8, 9]], 3) == [1, 2, 1]


def test_spec_example_2():
    assert minPath([[5, 9, 3], [4, 1, 6], [7, 8, 2]], 1) == [1]


# ---------- regression for left-edge wrap defect ----------

def test_left_edge_does_not_wrap_to_last_column():
    # 1 at (0,0); true neighbours are 9 and 8 -> min is 8.
    # Last column of same row holds 2, which is NOT adjacent to 1.
    grid = [
        [1, 9, 2],
        [8, 7, 6],
        [5, 4, 3],
    ]
    assert minPath(grid, 2) == [1, 8]
    assert minPath(grid, 3) == [1, 8, 1]
    assert minPath(grid, 4) == [1, 8, 1, 8]


def test_left_edge_middle_row_does_not_wrap():
    # 1 at (1,0); true neighbours: (0,0)=9,(2,0)=8,(1,1)=7 -> min 7
    # (1,2)=2 is not adjacent but is grid[1][-1].
    grid = [
        [9, 6, 5],
        [1, 7, 2],
        [8, 4, 3],
    ]
    # check with brute to avoid hardcoding mistake
    assert brute_min_path(grid, 3) == [1, 7, 1]
    assert minPath(grid, 3) == [1, 7, 1]


def test_one_at_bottom_left_does_not_wrap():
    grid = [
        [4, 5, 2],
        [6, 7, 8],
        [1, 9, 3],
    ]
    # neighbours of 1: (1,0)=6,(2,1)=9 -> min 6; wrap cell (2,2)=3 is not neighbour
    assert brute_min_path(grid, 2) == [1, 6]
    assert minPath(grid, 2) == [1, 6]
    assert minPath(grid, 5) == brute_min_path(grid, 5)


# ---------- properties ----------

@given(grid=_random_grid_strategy(2, 3), k=st.integers(min_value=1, max_value=5))
def test_property_matches_brute_force(grid, k):
    assert minPath(grid, k) == brute_min_path(grid, k)


@given(grid=_random_grid_strategy(2, 3), k=st.integers(min_value=1, max_value=5))
def test_property_length_is_k(grid, k):
    res = minPath(grid, k)
    assert isinstance(res, list)
    assert len(res) == k


@given(grid=_random_grid_strategy(2, 3), k=st.integers(min_value=1, max_value=6))
def test_property_starts_with_one(grid, k):
    # 1 is the globally smallest value, so lexicographically minimal path
    # must start with 1.
    res = minPath(grid, k)
    assert res[0] == 1


@given(grid=_random_grid_strategy(2, 3), k=st.integers(min_value=1, max_value=5))
def test_property_values_form_valid_walk(grid, k):
    res = minPath(grid, k)
    assert _is_valid_walk_values(grid, res), f"{res} is not a valid walk on {grid}"


@given(grid=_random_grid_strategy(2, 3), k=st.integers(min_value=1, max_value=5))
def test_property_lexicographically_minimal(grid, k):
    res = minPath(grid, k)
    # every single-cell start must be >= res[0], and res must beat
    # the walk that stays bouncing from an arbitrary cell is not needed;
    # instead check res <= all walks of length k from brute enumeration
    # by checking res equals brute min (already covered) — here check
    # res is <= a few canonical walks: bouncing around the cell holding 2.
    n = len(grid)
    # walk starting at 2 bouncing to its smallest neighbour must be >= res
    pos2 = _pos_of(grid, 2)
    r, c = pos2
    neigh_vals = []
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            neigh_vals.append(grid[nr][nc])
    mn2 = min(neigh_vals)
    cand = [2 if i % 2 == 0 else mn2 for i in range(k)]
    # only compare if cand is actually a valid walk (it is by construction
    # if we bounce between 2 and its min neighbour)
    assert res <= cand
    assert res <= brute_min_path(grid, k)
    assert res >= [1] * 0  # trivial sanity


def test_property_k_equals_1_always_one():
    # for any grid, k=1 answer must be [1]
    grids = [
        [[1, 2], [3, 4]],
        [[4, 3], [2, 1]],
        [[1, 9, 2], [8, 7, 6], [5, 4, 3]],
        [[5, 9, 3], [4, 1, 6], [7, 8, 2]],
    ]
    for g in grids:
        assert minPath(g, 1) == [1]


@given(grid=_random_grid_strategy(2, 3))
def test_property_even_positions_are_one_when_bouncing(grid):
    # The optimal walk must alternate back to 1 whenever possible;
    # in particular for the true optimum, every even index (0-based) is 1.
    # This follows because 1's cell is always reachable in one step from
    # the min-neighbour cell. Check the returned value satisfies it when
    # k is small, by comparison with brute force pattern.
    for k in (1, 2, 3, 4, 5):
        res = minPath(grid, k)
        exp = brute_min_path(grid, k)
        assert res == exp
        for i in range(0, k, 2):
            assert exp[i] == 1
            assert res[i] == 1
